<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Shared\Event\PublicEvent;

class TemplateAssetUpdateEvent extends TemplateAssetEvent implements PublicEvent
{
    public function __construct(
        TemplateAsset $payload,
        public readonly TemplateAsset $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'template-asset.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
